add_filter( 'woocommerce_payment_complete_order_status', 'perfectpixel_autocomplete_paid_orders', 10, 3 );

function perfectpixel_autocomplete_paid_orders( $status, $order_id, $order = null ) {
	if ( 'processing' !== $status ) {
		return $status;
	}
	$order = $order instanceof WC_Order ? $order : wc_get_order( $order_id );
	if ( ! $order ) {
		return $status;
	}
	if ( 'yes' === '{{autocomplete_virtual_only}}' ) {
		foreach ( $order->get_items() as $item ) {
			$product = $item->get_product();
			if ( ! $product || ! $product->is_virtual() ) {
				return $status;
			}
		}
	}
	return 'completed';
}
